package ru.library.frontend;

final class PageHelp {
    private PageHelp() { }

    static String text(String title) {
        return switch (title) {
            case "Каталог книг", "Каталог" -> "Каталог содержит описания изданий: название, авторов, ISBN и год. Одна запись книги может иметь несколько физических экземпляров.\n\nISBN — международный код конкретного издания, обычно 13 цифр. Номер записи — внутренний номер книги в нашей базе. Номер экземпляра (инвентарный) помечает конкретную копию на полке. Это разные номера.\n\nИщите по названию, автору или ISBN. Для выдачи отметьте одну книгу, нажмите «Выдать книгу» и выберите читателя. Backend проверит билет, штрафы и свободный экземпляр.\n\n«Архив книг» показывает снятые с рабочего каталога записи. Администратор может открыть карточку и восстановить книгу.";
            case "Читатели" -> "Читатели — посетители библиотеки, которым выдают книги. Они отличаются от сотрудников, входящих в приложение.\n\nОтметьте чекбоксами нескольких читателей, чтобы посмотреть их общую историю выдач или штрафов. Выбор сохраняется при переходе страниц. Карточка доступна при выборе ровно одного человека.\n\nЧитательский билет разрешает получать книги в указанном диапазоне дат включительно. «Оформить / продлить билет» используется при первом оформлении, продлении или замене потерянного билета. Новый билет отключает предыдущий, но история сохраняется.\n\nАдминистратор добавляет читателей и меняет данные. Сотрудник просматривает их и оформляет выдачи и возвраты.";
            case "Выдачи и возвраты" -> "Здесь показаны все выдачи. Фильтры: все выдачи, книги на руках, только просроченные, возвращённые книги. Можно ограничить список одним или несколькими читателями.\n\nДля возврата отметьте одну или несколько незавершённых выдач и нажмите «Вернуть выбранные книги». Дата возврата — текущая дата. Экземпляры снова станут доступными; при опоздании появятся штрафы. Возврат всей группы выполняется вместе: при ошибке изменения отменяются. Уже возвращённые книги повторно вернуть нельзя.\n\nШтраф = дни после запланированной даты возврата × ставка, сохранённая при выдаче. Изменение настроек не меняет ставку уже выданных книг.\n\n«На странице: 9 записей» означает девять строк в таблице. При количестве до 12 следующей страницы нет. Кнопки «Назад» и «Далее» доступны, только если есть другая страница. «Статистика» показывает показатели всей библиотеки.";
            case "Штрафы" -> "Штраф начисляется при возврате просроченной книги. До возврата просрочка видна в «Выдачи и возвраты», но начисленного штрафа ещё нет.\n\nПо умолчанию показаны штрафы всех читателей. Можно выбрать нескольких людей или включить «Только неоплаченные». Пустой список означает отсутствие начислений по выбранному фильтру.\n\nАдминистратор подтверждает оплату после получения денег. Приложение учитывает оплату, но не проводит денежные переводы. Пока есть неоплаченный штраф, новую книгу читателю выдать нельзя.";
            case "Справочники" -> "Это общие списки авторов, жанров и издательств, используемые при создании и редактировании книг. Это не отдельный поиск по каталогу.\n\nВыберите тип справочника. «Найти» в этом разделе фильтрует записи выбранного списка. Администратор может добавить, переименовать или удалить запись. Сотрудник просматривает её.\n\nНапример, добавьте автора «Лев Толстой», затем выберите его в форме книги. Для автора здесь хранится имя, для жанра — название («Роман»), для издательства — название.\n\nЗапись, на которую ссылается книга, удалить нельзя: сначала измените связь в карточке книги. Переименование меняет общую запись и отображается у связанных книг.";
            case "Сотрудники" -> "Учётные записи людей, работающих с приложением. Регистрация создаёт роль «Сотрудник» (user); администратор может назначать роли, отключать доступ и сбрасывать пароли.\n\nАдминистратор управляет каталогом, читателями, справочниками, настройками, штрафами и сотрудниками. Обычный сотрудник ищет книги, оформляет выдачи и возвраты, смотрит историю и статистику.\n\nПосле смены роли, пароля или отключения прежние сеансы становятся недействительными. Последнего активного администратора нельзя отключить или понизить. Пароли сохраняются в виде BCrypt-хешей.";
            case "Настройки" -> "Срок выдачи определяет, через сколько дней нужно вернуть новую книгу. Ставка штрафа — сумма за каждый день опоздания. Администратор меняет эти правила.\n\nНовые значения применяются к будущим выдачам; у старых сохраняются первоначальные дата возврата и ставка.\n\n«Изменить мой пароль» требует текущий пароль. После изменения нужно войти заново. Минимальная длина нового пароля — 10 символов.";
            case "Состояние системы" -> "Проверка подключения к PostgreSQL доступна администратору. Она показывает имя базы, версию сервера, время проверки, количество таблиц и сотрудников.\n\nВремя ответа относится к конкретной проверке приложения и зависит от подключения и нагрузки. Это не постоянный мониторинг всех запросов.\n\nНажмите «Проверить подключение». При ошибке проверьте службу PostgreSQL и локальные реквизиты подключения. Пользователями управляйте в разделе «Сотрудники».";
            default -> "Используйте действия на странице. Отмечайте строки перед выполнением операции; доступные действия зависят от роли сотрудника.";
        };
    }
}
